// 变换计划执行器 + 形状整形（适配器无关：ECharts / AntV / D3 复用同一套语义）。

import type { ChartData, ChartSpec, Row, TransformPlan } from "./spec";

// ── 变换计划执行 ────────────────────────────────────────

export function applyTransform(rows: Row[], plan: TransformPlan[]): Row[] {
  let out: Row[] = rows.slice();
  for (const step of plan) {
    switch (step.op) {
      case "filter":
        out = out.filter((r) => compare(r[step.dataKey], step.cmp, step.value));
        break;
      case "bucket":
        out = out.map((r) => ({ ...r, [step.as]: bucketValue(r[step.dataKey], step.by) }));
        break;
      case "aggregate":
        out = aggregate(out, step);
        break;
      case "sort":
        out = sortRows(out, step.dataKey, step.desc);
        break;
      case "limit":
        out = out.slice(0, step.n);
        break;
    }
  }
  return out;
}

function compare(actual: unknown, cmp: string, expected: string): boolean {
  const a = actual;
  const b = expected;
  switch (cmp) {
    case "eq":
      return String(a ?? "") === b;
    case "ne":
      return String(a ?? "") !== b;
    case "gt":
      return Number(a) > Number(b);
    case "gte":
      return Number(a) >= Number(b);
    case "lt":
      return Number(a) < Number(b);
    case "lte":
      return Number(a) <= Number(b);
    case "in":
      return b.split("|").includes(String(a ?? ""));
    default:
      return true;
  }
}

/** 时间分桶：返回可读标签（day → YYYY-MM-DD，month → YYYY-MM …）。 */
export function bucketValue(raw: unknown, unit: string): string {
  if (raw === null || raw === undefined || raw === "") return "";
  const d = raw instanceof Date ? raw : new Date(String(raw));
  if (Number.isNaN(d.getTime())) return String(raw);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0");
  switch (unit) {
    case "hour":
      return `${y}-${m}-${day} ${hh}`;
    case "week": {
      const start = new Date(d.getTime());
      const dow = (start.getDay() + 6) % 7; // 周一为一周之始
      start.setDate(start.getDate() - dow);
      return `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, "0")}-${String(
        start.getDate(),
      ).padStart(2, "0")}`;
    }
    case "month":
      return `${y}-${m}`;
    case "year":
      return `${y}`;
    case "day":
    default:
      return `${y}-${m}-${day}`;
  }
}

type AggregateStep = Extract<TransformPlan, { op: "aggregate" }>;

function aggregate(rows: Row[], step: AggregateStep): Row[] {
  const groups = new Map<string, Row[]>();
  const keys = step.groupKeys.length > 0 ? step.groupKeys : [];
  for (const row of rows) {
    const key = keys.map((k) => String(row[k] ?? "")).join("");
    const bucketRows = groups.get(key);
    if (bucketRows) bucketRows.push(row);
    else groups.set(key, [row]);
  }
  const out: Row[] = [];
  for (const [, bucketRows] of groups) {
    const values = bucketRows
      .map((r) => (step.dataKey ? Number(r[step.dataKey]) : 1))
      .filter((n) => Number.isFinite(n));
    let value: number;
    switch (step.agg) {
      case "sum":
        value = values.reduce((a, b) => a + b, 0);
        break;
      case "avg":
        value = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
        break;
      case "min":
        value = values.length ? Math.min(...values) : 0;
        break;
      case "max":
        value = values.length ? Math.max(...values) : 0;
        break;
      case "count":
      default:
        value = bucketRows.length;
        break;
    }
    const out_row: Row = { [step.as]: value };
    // 分组键用运行时数据键（groupKeys），与 channel.dataKey 对齐
    keys.forEach((k) => {
      out_row[k] = bucketRows.length ? bucketRows[0][k] : undefined;
    });
    out.push(out_row);
  }
  return out;
}

function sortRows(rows: Row[], dataKey: string, desc: boolean): Row[] {
  const copy = rows.slice();
  copy.sort((a, b) => {
    const av = a[dataKey];
    const bv = b[dataKey];
    let cmp: number;
    if (typeof av === "number" && typeof bv === "number") cmp = av - bv;
    else cmp = String(av ?? "").localeCompare(String(bv ?? ""));
    return desc ? -cmp : cmp;
  });
  return copy;
}

// ── 形状整形 ────────────────────────────────────────────

export function shapeData(spec: ChartSpec, rows: Row[]): ChartData {
  switch (spec.shape) {
    case "cartesian":
      return shapeCartesian(spec, rows);
    case "xy":
      return shapeXy(spec, rows);
    case "part-to-whole":
      return shapePairs(spec, rows);
    case "gauge":
      return shapeGauge(spec, rows);
    case "radial":
      return shapeRadial(spec, rows);
    case "heatmap":
      return shapeHeatmap(spec, rows);
  }
}

function num(v: unknown): number | null {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function shapeCartesian(spec: ChartSpec, rows: Row[]): ChartData {
  const xKey = spec.encoding.x?.dataKey ?? "";
  const yKey = spec.encoding.y?.dataKey ?? "";
  const seriesKey = spec.encoding.series?.dataKey;
  const temporal = spec.encoding.x?.valueType === "temporal";

  const categories: Array<string | number> = [];
  const seen = new Set<string>();
  for (const row of rows) {
    const raw = row[xKey];
    const key = String(raw ?? "");
    if (seen.has(key)) continue;
    seen.add(key);
    categories.push(temporal ? epochMs(raw) : key);
  }

  const groups = new Map<string, Row[]>();
  if (seriesKey) {
    for (const row of rows) {
      const name = String(row[seriesKey] ?? "");
      const bucket = groups.get(name);
      if (bucket) bucket.push(row);
      else groups.set(name, [row]);
    }
  } else {
    groups.set("", rows);
  }

  const series = Array.from(groups.entries()).map(([name, bucketRows]) => {
    const byCategory = new Map<string, number | null>();
    for (const row of bucketRows) {
      byCategory.set(String(row[xKey] ?? ""), num(row[yKey]));
    }
    const data = categories.map((c) => {
      const v = byCategory.get(String(c));
      return v === undefined ? null : v;
    });
    return { name, data };
  });

  return { kind: "cartesian", categories, series };
}

function epochMs(raw: unknown): number {
  if (raw === null || raw === undefined || raw === "") return 0;
  if (typeof raw === "number") return raw;
  const t = new Date(String(raw)).getTime();
  return Number.isNaN(t) ? 0 : t;
}

function shapeXy(spec: ChartSpec, rows: Row[]): ChartData {
  const xKey = spec.encoding.x?.dataKey ?? "";
  const yKey = spec.encoding.y?.dataKey ?? "";
  const points: Array<[number, number]> = [];
  for (const row of rows) {
    const x = num(row[xKey]);
    const y = num(row[yKey]);
    if (x === null || y === null) continue;
    points.push([x, y]);
  }
  return { kind: "xy", points };
}

function shapePairs(spec: ChartSpec, rows: Row[]): ChartData {
  const xKey = spec.encoding.x?.dataKey ?? "";
  const yKey = spec.encoding.y?.dataKey ?? "";
  const items: Array<{ name: string; value: number }> = [];
  for (const row of rows) {
    const value = num(row[yKey]);
    if (value === null) continue;
    items.push({ name: String(row[xKey] ?? ""), value });
  }
  return { kind: "pairs", items };
}

function shapeGauge(spec: ChartSpec, rows: Row[]): ChartData {
  const yKey = spec.encoding.y?.dataKey ?? "";
  const first = rows.length ? num(rows[0][yKey]) : null;
  return { kind: "gauge", value: first ?? 0 };
}

function shapeRadial(spec: ChartSpec, rows: Row[]): ChartData {
  const xKey = spec.encoding.x?.dataKey ?? "";
  const yKey = spec.encoding.y?.dataKey ?? "";
  const indicators: string[] = [];
  const values: number[] = [];
  const seen = new Set<string>();
  for (const row of rows) {
    const name = String(row[xKey] ?? "");
    if (seen.has(name)) continue;
    seen.add(name);
    indicators.push(name);
    values.push(num(row[yKey]) ?? 0);
  }
  return { kind: "radial", indicators, values };
}

function shapeHeatmap(spec: ChartSpec, rows: Row[]): ChartData {
  const xKey = spec.encoding.x?.dataKey ?? "";
  const yKey = spec.encoding.y?.dataKey ?? "";
  const valueKey = spec.encoding.color?.dataKey ?? spec.encoding.y?.dataKey ?? "";
  const xLabels: string[] = [];
  const yLabels: string[] = [];
  const xSeen = new Set<string>();
  const ySeen = new Set<string>();
  for (const row of rows) {
    const x = String(row[xKey] ?? "");
    const y = String(row[yKey] ?? "");
    if (!xSeen.has(x)) {
      xSeen.add(x);
      xLabels.push(x);
    }
    if (!ySeen.has(y)) {
      ySeen.add(y);
      yLabels.push(y);
    }
  }
  const cells: Array<[number, number, number]> = [];
  for (const row of rows) {
    const xi = xLabels.indexOf(String(row[xKey] ?? ""));
    const yi = yLabels.indexOf(String(row[yKey] ?? ""));
    const v = num(row[valueKey]);
    if (xi < 0 || yi < 0 || v === null) continue;
    cells.push([xi, yi, v]);
  }
  return { kind: "heatmap", xLabels, yLabels, cells };
}
